SELECT CASE WHEN balance >= 74000 THEN 'high' WHEN balance >= 28000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND(STDDEV(balance), 2) AS stddev_balance, MIN(opened_date) AS min_opened_date, MAX(balance) - MIN(balance) AS balance_range FROM accounts WHERE account_type IN ('LOAN', 'SAVINGS') OR customer_id IS NOT NULL GROUP BY 1 HAVING stddev_balance >= 33 ORDER BY min_opened_date;
